fixture.setup:
mkdir -p fixture/src && cd fixture && cat > src/index.js << 'EOF'
console.log('DEBUG: payment service starting'); // FINDING: debug code in production

export function processPayment(amount, currency) {
  if (amount <= 0) throw new Error('Invalid amount');
  return { id: 'pay_' + Date.now(), amount, currency, status: 'completed' };
}
EOF
cat > src/index.test.js << 'EOF'
import { processPayment } from './index.js';
test('processes valid payment', () => {
  const result = processPayment(100, 'USD');
  expect(result.amount).toBe(100);
  expect(result.currency).toBe('USD');
});
test('rejects invalid amount', () => {
  expect(() => processPayment(-10, 'USD')).toThrow('Invalid amount');
});
EOF
cat > package.json << 'EOF'
{
  "name": "payment-service",
  "version": "1.0.0",
  "description": "",
  "main": "src/index.js",
  "scripts": { "test": "node --test src/index.test.js", "build": "echo 'no build step'" },
  "license": "MIT",
  "type": "module"
}
EOF
cat > CHANGELOG.md << 'EOF'
# Changelog

## 1.0.0 - Unreleased

### Added
- Initial payment processing
EOF
cd fixture && npm install
